"""tests/parity/expected.json is generated by the JavaScript reference
(plagx-preflight, npm run parity). Every case must match exactly."""
import json
from pathlib import Path

import pytest

from plagx_preflight import VERSION, check_draft

HERE = Path(__file__).parent
DATA = json.loads((HERE / "parity" / "expected.json").read_text(encoding="utf-8"))
NAMES = {"minWords": "min_words", "maxWords": "max_words", "requiredHeadings": "required_headings"}


def _options(name):
    return {NAMES.get(k, k): v for k, v in DATA["optionSets"][name].items()}


@pytest.mark.parametrize("case", DATA["cases"], ids=lambda c: f"{c['fixture']}/{c['options']}")
def test_matches_javascript(case):
    text = (HERE / "fixtures" / case["fixture"]).read_bytes().decode("utf-8")
    result = check_draft(text, **_options(case["options"]))
    dump = lambda d: json.dumps(d, ensure_ascii=False, indent=2)  # noqa: E731
    assert dump(result) == dump(case["result"])


def test_covers_every_fixture():
    assert len(DATA["cases"]) == 160
    assert DATA["version"] == VERSION
